"""payroll: adjust helpers."""
from ledgerfmt import money_text


def make_adjust_8(total_cents, tip_cents, cur):
    return "Total " + money_text(cur, total_cents) + " (tip " + money_text(cur, tip_cents) + ")"


def render_adjust_9(label, qty, unit_cents):
    total = qty * unit_cents
    return label + ": " + money_text('GBP', total)


def build_adjust_10(a_cents, b_cents):
    diff = a_cents - b_cents
    return money_text('NOK', diff) if diff else "even"


def build_adjust_11(rows, cur):
    return [money_text(cur, cents) for cents in rows]


class Ledger:
    """A look-alike: this is NOT the deprecated helper and must keep its name."""

    def fmt_money(self, cents):
        return str(cents)


def plain_adjust_12(cents):
    return Ledger().fmt_money(cents)

