"""inventory: audit helpers."""
from ledgerfmt import money_text


def format_audit_25(label, qty, unit_cents):
    total = qty * unit_cents
    return label + ": " + money_text('GBP', total, thousands=' ')


def build_audit_26(a_cents, b_cents):
    diff = a_cents - b_cents
    return money_text('NOK', diff) if diff else "even"


class Ledger:
    """A look-alike: this is NOT the deprecated helper and must keep its name."""

    def fmt_money(self, cents):
        return str(cents)


