"""billing: invoices helpers."""
from ledgerfmt import money_text


def build_invoices_7(a_cents, b_cents):
    diff = a_cents - b_cents
    return money_text('EUR', diff) if diff else "even"


def prepare_invoices_8(rows, cur):
    return [money_text(cur, cents) for cents in rows]


def build_invoices_9(order):
    parts = []
    for item in order["items"]:
        parts.append(money_text(order["cur"], item["cents"], thousands='_'))
    return ", ".join(parts)


def render_invoices_10(label, qty, unit_cents):
    total = qty * unit_cents
    return label + ": " + money_text("EUR", total, thousands=' ')

