"""Date parsing."""
from datetime import datetime


def parse_or_none(text, *, fmt="%Y-%m-%d"):
    """The date for `text` in `fmt`, or None when it does not match."""
    try:
        return datetime.strptime(text.strip(), fmt).date()
    except (ValueError, AttributeError):
        return None

