            fail("%s.%s(%r) raised %s: %s" % (c["module"], c["fn"], c["args"], type(e).__name__, e))
        got = {"result": res}
        if capture:
            got["records"] = [list(r) for r in obslog.RECORDS]
        got = json.loads(json.dumps(got))
        if got != w:
            fail("%s.%s(%r)\n  got  %r\n  want %r" % (c["module"], c["fn"], c["args"], got, w))


