                fail("with the legacy helpers removed, %s breaks: %s" % (svc, p.stderr[-400:]))
    elif what == "behaviour":
        behaviour(sys.argv[3], sys.argv[2])
    else:
        static(os.getcwd(), what)
        behaviour(os.getcwd(), what)

